import{_ as t,o,c as a,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"FR 3.7.3 — View Brand Knowledge Documents","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/06-ai-features/3-7-3-view-brand-knowledge-documents/spec.md","filePath":"feature/srs/06-ai-features/3-7-3-view-brand-knowledge-documents/spec.md"}'),n={name:"feature/srs/06-ai-features/3-7-3-view-brand-knowledge-documents/spec.md"};function r(c,e,i,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-7-3-—-view-brand-knowledge-documents" tabindex="-1">FR 3.7.3 — View Brand Knowledge Documents <a class="header-anchor" href="#fr-3-7-3-—-view-brand-knowledge-documents" aria-label="Permalink to &quot;FR 3.7.3 — View Brand Knowledge Documents&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.7.3</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-090</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">View Brand Knowledge Documents</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">AI Features (<code>3.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20</code>, <code>BR-46</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01</code>, <code>MSG02</code>, <code>MSG03</code>, <code>MSG07</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Enable <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, and <code>Client</code> members of a Workspace to view indexed Brand Guideline documents and execute live semantic similarity previews against the Workspace-isolated ChromaDB vector store (<code>brand_docs_{workspace_id}</code>, <code>BR-20</code>, <code>BR-46</code>). This provides full transparency into which brand tone rules, product specifications, and compliance policies ground AI Caption and Image/Video generation.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, or <code>Client</code> in a Workspace, I want to inspect all uploaded Brand Knowledge documents, their vectorization status (<code>PENDING</code>, <code>INDEXED</code>, <code>FAILED</code>), chunk counts, and semantic retrieval relevance scores so that I can verify AI grounding accuracy before generating campaign assets.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Workspace Tenant Isolation (<code>BR-20</code>, <code>BR-46</code>):</strong> Only authenticated members (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>) of <code>{workspaceId}</code> can list documents or run semantic preview queries; every ChromaDB lookup binds server-verified <code>workspace_id</code> collection scope (<code>brand_docs_{workspace_id}</code>) and never trusts client-supplied collection names (<code>MSG07</code>).</li><li><strong>Document Inventory &amp; Indexing Metadata:</strong> Each listed document displays filename, MIME type (<code>PDF</code>, <code>DOCX</code>, <code>TXT</code>, <code>MD</code>), file size, uploader display name, <code>createdAt</code>, indexing status (<code>PENDING</code>, <code>INDEXED</code>, <code>FAILED</code>), and embedded chunk count (<code>chunkCount</code>).</li><li><strong>Semantic Retrieval Preview (<code>SemanticSearchBar.tsx</code>):</strong> Users can enter a test query (e.g., <em>&quot;chính sách bảo hành sản phẩm&quot;</em>) to inspect top-<code>k</code> (<code>k &lt;= 5</code>) matching chunks with cosine similarity score (<code>&gt;= 0.70</code> grounding threshold indicator) without consuming AI Credits.</li><li><strong>Role-Gated Mutation Affordances:</strong> <code>Creator</code> sees read-only document list and semantic search; Upload (FR 3.7.4) and Delete (FR 3.7.5) buttons render only for <code>Owner</code>, <code>Manager</code>, and <code>Client</code>.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All table headers, indexing status badges, semantic search placeholders, and empty states use synchronized keys under <code>aiStudio.knowledgeBase.*</code> in <code>vi.json</code> and <code>en.json</code>.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> <code>pages/ai-studio/knowledge-base/index.tsx</code>, <code>DocumentList.tsx</code>, and <code>SemanticSearchBar.tsx</code> use semantic surface/border/badge tokens supporting both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Route:</strong> <code>/workspaces/:workspaceId/ai-studio/knowledge-base</code> (<code>pages/ai-studio/knowledge-base/index.tsx</code>, <code>DocumentList.tsx</code>, <code>SemanticSearchBar.tsx</code>).</li><li><strong>UI States:</strong><ul><li><strong>Loading:</strong> Skeleton rows for document list + disabled search input during fetch.</li><li><strong>Empty:</strong> Guided onboarding card explaining how Brand RAG prevents LLM hallucination, with CTA to FR 3.7.4 for <code>Owner</code>/<code>Manager</code>/<code>Client</code>.</li><li><strong>Indexing In Progress:</strong> Live status pill (<code>PENDING</code>) polling until chunk embedding completes (<code>INDEXED</code>) or surfaces failure reason (<code>FAILED</code>).</li><li><strong>Error:</strong> <code>AiStudioErrorBanner.tsx</code> displaying localized message mapped from <code>ErrorCode</code> (<code>MSG03</code>, <code>MSG07</code>).</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Caller Role</th><th style="text-align:left;">Handler</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/workspaces/{workspaceId}/ai/knowledge/documents</code></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td><td style="text-align:left;">Business RAG proxy -&gt; <code>ai-service</code> <code>rag.py</code></td><td style="text-align:left;">Paginated list of workspace brand documents + indexing status</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/knowledge/query</code></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td><td style="text-align:left;"><code>VectorStoreService.query_similar_chunks()</code></td><td style="text-align:left;">Zero-credit semantic similarity preview (<code>topK &lt;= 5</code>)</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): User is not an active member of <code>{workspaceId}</code>.</li><li><code>INVALID_SEARCH_QUERY</code> (<code>400</code>, <code>MSG02</code>): Blank semantic query or query exceeding <code>500</code> characters.</li><li><code>VECTOR_STORE_UNAVAILABLE</code> (<code>503</code>, <code>MSG03</code>): ChromaDB connection failure; metadata list from PostgreSQL/MongoDB still renders with a warning banner that semantic preview is temporarily unavailable.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Sibling SRS FRs:</strong> <a href="./../3-7-4-upload-brand-knowledge-document/spec.html">FR 3.7.4 — Upload Brand Knowledge Document</a> · <a href="./../3-7-5-delete-brand-knowledge-document/spec.html">FR 3.7.5 — Delete Brand Knowledge Document</a> · <a href="./../3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.html"><code>rag-caption-moderation-and-humanizer</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/06-ai-features.html">BA 3.7 AI Features</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Strict <code>brand_docs_{workspace_id}</code> collection isolation verified in unit/integration tests, semantic preview UI wired with <code>vi</code>/<code>en</code> i18n and Light/Dark tokens, all test cases in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> Editing raw text inside embedded PDF/DOCX chunks (users re-upload updated documents via FR 3.7.4).</li></ul>',19)])])}const p=t(n,[["render",r]]);export{h as __pageData,p as default};
